script:
frappe.listview_settings['ToDo'] = {
	// Make sure reference_type / reference_name are SELECTed by the listview query
	add_fields: ['reference_type', 'reference_name'],

	onload: function(listview) {
		// Intercept clicks on rows whose ToDo references a Lead and route to the Activity Hub.
		// Synchronous: reference_type/reference_name come from listview.data, not an async fetch,
		// so preventDefault/stopImmediatePropagation actually fire BEFORE Frappe's default navigation.
		listview.$result.on('click', '.list-row', function(e) {
			var $row = $(this);
			var name = $row.attr('data-name');
			if (!name) return;

			var doc = (listview.data || []).find(function(d) { return d.name === name; });
			if (!doc || doc.reference_type !== 'Lead' || !doc.reference_name) return;

			// Ignore clicks on the checkbox, inline buttons, or badge links
			if ($(e.target).closest('input, .list-row-checkbox, .btn, .badge-link, .label').length) return;

			e.preventDefault();
			e.stopImmediatePropagation();
			frappe.set_route('lead-activity', doc.reference_name);
		});
	},

	refresh: function(listview) {
		// Rewrite the row anchor href so middle-click / cmd-click opens the hub in a new tab
		// instead of the default ToDo form.
		(listview.data || []).forEach(function(d) {
			if (d.reference_type === 'Lead' && d.reference_name) {
				var $row = listview.$result.find('[data-name="' + d.name + '"]');
				$row.find('a.ellipsis').attr('href', '/app/lead-activity/' + encodeURIComponent(d.reference_name));
			}
		});
	}
};
